 65	/// Owns all values made by its constructors, including parsed strings. Never copy
 66	/// a live Graph. Handles belong to this graph and survive growth. Returned views
 67	/// must not be retained across mutation. Release the graph once with deinit.
 68	pub const Graph = struct {
 69	    arena: std.heap.ArenaAllocator,
 70	    nodes: std.ArrayList(Node) = .empty,
 71	    bytes: std.AutoHashMapUnmanaged(ByteKey, ByteInfo) = .empty,
 72	
 73	    pub fn init(gpa: std.mem.Allocator) Graph {
 74	        return .{ .arena = .init(gpa) };
 75	    }
 76	    pub fn deinit(self: *Graph) void {
 77	        self.arena.deinit();
 78	        self.* = undefined;
 79	    }
 80	    pub fn allocator(self: *Graph) std.mem.Allocator {
 81	        return self.arena.allocator();
 82	    }
 83	    pub fn string(self: *Graph, bytes: []const u8) Error!Value {
 84	        if (!std.unicode.utf8ValidateSlice(bytes)) return error.UnsupportedString;
 85	        const copy = try self.allocator().dupe(u8, bytes);
 86	        try self.bytes.put(self.allocator(), byteKey(copy), .{ .hash = std.hash.Wyhash.hash(0, copy), .bigint = false });
 87	        return .{ .string = copy };
 88	    }
 89	    pub fn bigint(self: *Graph, digits: []const u8) Error!Value {
 90	        if (!canonicalBigInt(digits)) return error.UnsupportedValue;
 91	        const copy = try self.allocator().dupe(u8, digits);
 92	        try self.bytes.put(self.allocator(), byteKey(copy), .{ .hash = std.hash.Wyhash.hash(0, copy), .bigint = true });
 93	        return .{ .bigint = copy };
 94	    }
 95	    fn add(self: *Graph, new_node: Node) Error!Value {
 96	        if (self.nodes.items.len >= std.math.maxInt(u32)) return error.UnsupportedValue;
 97	        const handle: Handle = @fromBackingInt(@intCast(@as(u32, @intCast(self.nodes.items.len))));
 98	        try self.nodes.append(self.allocator(), new_node);
 99	        return .{ .ref = handle };
100	    }
101	    pub fn object(self: *Graph, null_proto: bool) Error!Value {
102	        return self.add(.{ .object = .{ .null_proto = null_proto } });
103	    }
104	    pub fn array(self: *Graph, length: u32) Error!Value {
105	        return self.add(.{ .array = .{ .length = length } });
106	    }
107	    pub fn map(self: *Graph) Error!Value {
108	        return self.add(.{ .map = .{} });
109	    }
110	    pub fn set(self: *Graph) Error!Value {
111	        return self.add(.{ .set = .{} });
112	    }
113	    pub fn date(self: *Graph, millis: i64) Error!Value {
114	        if (millis < -8640000000000000 or millis > 8640000000000000) return error.UnsupportedValue;
