117	    pub fn regexp(self: *Graph, source: []const u8, flags: []const u8) Error!Value {
118	        if (!std.unicode.utf8ValidateSlice(source)) return error.UnsupportedString;
119	        var canonical: [8]u8 = undefined;
120	        const len = try canonicalFlags(flags, &canonical);
121	        const a = self.allocator();
122	        return self.add(.{ .regexp = .{ .source = try a.dupe(u8, source), .flags = try a.dupe(u8, canonical[0..len]) } });
