135	    pub fn validate(self: *const Graph, value: Value) Error!void {
136	        switch (value) {
137	            .ref => |h| {
138	                if (@backingInt(h) >= self.nodes.items.len) return error.InvalidHandle;
139	            },
140	            .string => |s| {
141	                if (!self.bytes.contains(byteKey(s)) and !std.unicode.utf8ValidateSlice(s)) return error.UnsupportedString;
142	            },
143	            .bigint => |s| {
144	                if (!(if (self.bytes.get(byteKey(s))) |info| info.bigint else false) and !canonicalBigInt(s)) return error.UnsupportedValue;
