149	    fn rawNode(self: *const Graph, value: Value) Error!Node {
150	        if (value != .ref) return error.InvalidType;
151	        try self.validate(value);
152	        return self.nodes.items[@backingInt(value.ref)];
153	    }
154	    pub fn node(self: *Graph, value: Value) Error!Node {
155	        const n = try self.nodePtr(value);
156	        switch (n.*) {
157	            .object => |*obj| if (!obj.ordered) {
158	                std.mem.sort(Property, obj.properties.items, {}, propertyLess);
159	                for (obj.properties.items, 0..) |prop, i| obj.lookup.getPtr(prop.key).?.* = i;
160	                obj.ordered = true;
161	            },
162	            .array => |*arr| if (!arr.ordered) {
163	                std.mem.sort(Element, arr.elements.items, {}, elementLess);
164	                for (arr.elements.items, 0..) |element, i| arr.lookup.getPtr(element.index).?.* = i;
165	                arr.ordered = true;
166	            },
167	            else => {},
168	        }
169	        return n.*;
170	    }
171	    fn nodePtr(self: *Graph, value: Value) Error!*Node {
172	        if (value != .ref) return error.InvalidType;
173	        try self.validate(value);
174	        return &self.nodes.items[@backingInt(value.ref)];
175	    }
176	    /// Properties enumerate in JS order: array-index keys first, numerically,
177	    /// followed by other keys in insertion order. __proto__ is not supported.
178	    pub fn put(self: *Graph, target: Value, key: []const u8, value: Value) Error!void {
179	        try self.validate(value);
180	        if (!std.unicode.utf8ValidateSlice(key)) return error.UnsupportedString;
181	        if (std.mem.eql(u8, key, "__proto__")) return error.UnsupportedValue;
182	        const n = try self.nodePtr(target);
183	        if (n.* != .object) return error.InvalidType;
184	        if (n.object.lookup.get(key)) |i| {
185	            n.object.properties.items[i].value = value;
186	            return;
187	        }
188	        const a = self.allocator();
189	        try n.object.properties.ensureUnusedCapacity(a, 1);
190	        try n.object.lookup.ensureUnusedCapacity(a, 1);
191	        const copy = try a.dupe(u8, key);
192	        if (n.object.next_order == std.math.maxInt(usize)) return error.UnsupportedValue;
193	        const i = n.object.properties.items.len;
194	        n.object.properties.appendAssumeCapacity(.{ .key = copy, .value = value, .order = n.object.next_order });
195	        n.object.next_order += 1;
196	        n.object.lookup.putAssumeCapacity(copy, i);
197	        n.object.ordered = false;
198	    }
199	    pub fn remove(self: *Graph, target: Value, key: []const u8) Error!bool {
200	        const n = try self.nodePtr(target);
201	        if (n.* != .object) return error.InvalidType;
202	        const i = n.object.lookup.get(key) orelse return false;
203	        _ = n.object.lookup.remove(key);
204	        _ = n.object.properties.swapRemove(i);
205	        if (i < n.object.properties.items.len) n.object.lookup.getPtr(n.object.properties.items[i].key).?.* = i;
206	        n.object.ordered = false;
207	        return true;
208	    }
209	    pub fn get(self: *const Graph, target: Value, key: []const u8) Error!?Value {
210	        const n = try self.rawNode(target);
211	        if (n != .object) return error.InvalidType;
212	        return if (n.object.lookup.get(key)) |i| n.object.properties.items[i].value else null;
213	    }
214	    pub fn arrayPut(self: *Graph, target: Value, index: u32, value: Value) Error!void {
215	        try self.validate(value);
216	        const n = try self.nodePtr(target);
217	        if (n.* != .array or index >= n.array.length) return error.InvalidType;
218	        if (n.array.lookup.get(index)) |i| {
219	            n.array.elements.items[i].value = value;
220	            return;
221	        }
222	        const a = self.allocator();
223	        try n.array.elements.ensureUnusedCapacity(a, 1);
224	        try n.array.lookup.ensureUnusedCapacity(a, 1);
225	        const i = n.array.elements.items.len;
226	        if (i > 0 and n.array.elements.items[i - 1].index > index) n.array.ordered = false;
227	        n.array.elements.appendAssumeCapacity(.{ .index = index, .value = value });
228	        n.array.lookup.putAssumeCapacity(index, i);
229	    }
230	    /// null means a hole; .undefined means an explicitly populated undefined.
231	    pub fn arrayGet(self: *const Graph, target: Value, index: u32) Error!?Value {
232	        const n = try self.rawNode(target);
233	        if (n != .array or index >= n.array.length) return error.InvalidType;
234	        return if (n.array.lookup.get(index)) |i| n.array.elements.items[i].value else null;
235	    }
236	    pub fn mapPut(self: *Graph, target: Value, key: Value, value: Value) Error!void {
237	        try self.validate(key);
238	        try self.validate(value);
239	        const n = try self.nodePtr(target);
240	        if (n.* != .map) return error.InvalidType;
241	        const ctx = ValueContext{ .graph = self };
242	        if (n.map.lookup.getContext(key, ctx)) |i| {
243	            n.map.entries.items[i].value = value;
244	            return;
245	        }
246	        const a = self.allocator();
247	        try n.map.entries.ensureUnusedCapacity(a, 1);
248	        try n.map.lookup.ensureUnusedCapacityContext(a, 1, ctx);
249	        const i = n.map.entries.items.len;
250	        n.map.entries.appendAssumeCapacity(.{ .key = normalizeZero(key), .value = value });
251	        n.map.lookup.putAssumeCapacityContext(normalizeZero(key), i, ctx);
252	    }
253	    pub fn setAdd(self: *Graph, target: Value, value: Value) Error!void {
254	        try self.validate(value);
255	        const n = try self.nodePtr(target);
256	        if (n.* != .set) return error.InvalidType;
257	        const ctx = ValueContext{ .graph = self };
258	        if (n.set.lookup.containsContext(value, ctx)) return;
259	        const a = self.allocator();
260	        try n.set.values.ensureUnusedCapacity(a, 1);
261	        try n.set.lookup.ensureUnusedCapacityContext(a, 1, ctx);
262	        n.set.values.appendAssumeCapacity(normalizeZero(value));
263	        n.set.lookup.putAssumeCapacityContext(normalizeZero(value), {}, ctx);
264	    }
265	};
