270	pub fn equal(a: Value, b: Value) bool {
271	    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
272	    return switch (a) {
273	        .null, .undefined => true,
274	        .boolean => |v| v == b.boolean,
275	        .number => |v| v == b.number or (std.math.isNan(v) and std.math.isNan(b.number)),
276	        .string => |v| bytesEqual(v, b.string),
277	        .bigint => |v| bytesEqual(v, b.bigint),
278	        .ref => |v| v == b.ref,
279	    };
280	}
281	fn normalizeZero(v: Value) Value {
282	    return if (v == .number and v.number == 0) .{ .number = 0 } else v;
283	}
284	pub fn canonicalBigInt(s: []const u8) bool {
285	    if (std.mem.eql(u8, s, "0")) return true;
286	    const digits = if (s.len > 0 and s[0] == '-') s[1..] else s;
287	    if (digits.len == 0 or digits[0] < '1' or digits[0] > '9') return false;
288	    for (digits) |c| if (c < '0' or c > '9') return false;
289	    return true;
290	}
291	pub fn arrayIndex(s: []const u8) ?u32 {
292	    if (s.len == 0 or s.len > 10 or (s.len > 1 and s[0] == '0')) return null;
293	    for (s) |c| if (c < '0' or c > '9') return null;
294	    const n = std.fmt.parseInt(u32, s, 10) catch return null;
295	    return if (n == std.math.maxInt(u32)) null else n;
296	}
297	fn canonicalFlags(flags: []const u8, out: *[8]u8) Error!usize {
298	    const order = "dgimsuvy";
299	    var seen: [8]bool = @splat(false);
300	    for (flags) |flag| {
301	        const i = std.mem.indexOfScalar(u8, order, flag) orelse return error.UnsupportedValue;
302	        if (seen[i]) return error.UnsupportedValue;
303	        seen[i] = true;
304	    }
305	    if (seen[5] and seen[6]) return error.UnsupportedValue;
306	    var len: usize = 0;
307	    for (order, seen) |c, yes| if (yes) {
308	        out[len] = c;
309	        len += 1;
310	    };
311	    return len;
312	}
