  1	// A flat token tape, not a JSON value tree. Container tokens point to their
  2	// matching close; devalue slot IDs map to start offsets. Strings borrow input
  3	// where the scanner can, and are copied only when retained by the result graph.
  4	const std = @import("std");
  5	const d = @import("root.zig");
  6	pub const Atom = struct { token: std.json.Token, end: usize = 0, children: usize = 0 };
  7	pub const Tape = struct {
  8	    atoms: []const Atom,
  9	    pub fn next(self: Tape, i: usize) usize {
 10	        return switch (self.atoms[i].token) {
 11	            .array_begin, .object_begin => self.atoms[i].end + 1,
 12	            else => i + 1,
 13	        };
 14	    }
 15	    pub fn child(self: Tape, i: usize, n: usize) d.Error!usize {
 16	        if (n >= self.atoms[i].children) return error.InvalidDocument;
 17	        var pos = i + 1;
 18	        for (0..n) |_| pos = self.next(pos);
 19	        return pos;
 20	    }
 21	    pub fn string(self: Tape, i: usize) d.Error![]const u8 {
 22	        return switch (self.atoms[i].token) {
 23	            .string, .allocated_string => |s| s,
 24	            else => error.InvalidDocument,
 25	        };
 26	    }
 27	    pub fn number(self: Tape, i: usize) d.Error!f64 {
 28	        const s = switch (self.atoms[i].token) {
 29	            .number, .allocated_number => |s| s,
 30	            else => return error.InvalidDocument,
 31	        };
 32	        return std.fmt.parseFloat(f64, s) catch error.InvalidDocument;
 33	    }
 34	    pub fn reference(self: Tape, i: usize) d.Error!i64 {
 35	        const f = try self.number(i);
 36	        if (!std.math.isFinite(f) or @trunc(f) != f or f < -7 or f >= 9223372036854775808.0) return error.InvalidDocument;
 37	        return @intFromFloat(f);
 38	    }
 39	};
 40	pub fn scan(a: std.mem.Allocator, bytes: []const u8) d.Error!Tape {
 41	    var scanner = std.json.Scanner.initCompleteInput(a, bytes);
 42	    defer scanner.deinit();
 43	    var atoms: std.ArrayList(Atom) = .empty;
 44	    var stack: std.ArrayList(usize) = .empty;
 45	    while (true) {
 46	        const token = scanner.nextAllocMax(a, .alloc_if_needed, bytes.len) catch |err| return if (err == error.OutOfMemory) error.OutOfMemory else error.InvalidDocument;
 47	        if (token == .end_of_document) break;
 48	        const i = atoms.items.len;
 49	        switch (token) {
 50	            .array_end, .object_end => {
 51	                const open = stack.pop() orelse return error.InvalidDocument;
 52	                atoms.items[open].end = i;
 53	            },
 54	            else => {
 55	                if (stack.items.len > 0) atoms.items[stack.items[stack.items.len - 1]].children += 1;
 56	            },
 57	        }
 58	        try atoms.append(a, .{ .token = token });
 59	        if (token == .array_begin or token == .object_begin) {
 60	            if (stack.items.len >= d.max_depth) return error.DepthLimit;
 61	            try stack.append(a, i);
 62	        }
 63	    }
 64	    if (atoms.items.len == 0 or stack.items.len != 0) return error.InvalidDocument;
 65	    return .{ .atoms = atoms.items };
 66	}
