  5	/// Input is borrowed only during parsing. The returned graph owns every retained
  6	/// byte. Revivers may observe partial payloads and be invoked more than once.
  7	pub fn parse(gpa: std.mem.Allocator, bytes: []const u8, revivers: []const d.Reviver) d.Error!d.ParseResult {
  8	    var temp: std.heap.ArenaAllocator = .init(gpa);
  9	    defer temp.deinit();
 10	    const a = temp.allocator();
 11	    const tape = try w.scan(a, bytes);
 12	    var graph = d.Graph.init(gpa);
 13	    errdefer graph.deinit();
 14	    var dec = Decoder{ .a = a, .graph = &graph, .revivers = revivers, .tape = tape };
 15	    const root = tape.atoms[0];
 16	    var value: d.Value = undefined;
 17	    if (root.token == .number or root.token == .allocated_number) {
 18	        value = try dec.hydrate(try tape.reference(0), true, 0);
 19	    } else {
 20	        if (root.token != .array_begin or root.children == 0) return error.InvalidDocument;
 21	        try dec.values.ensureTotalCapacity(a, root.children);
 22	        try dec.cache.appendNTimes(a, null, root.children);
 23	        try dec.pending.appendNTimes(a, false, root.children);
 24	        var pos: usize = 1;
 25	        while (pos < root.end) : (pos = tape.next(pos)) dec.values.appendAssumeCapacity(pos);
 26	        value = try dec.hydrate(0, false, 0);
 27	    }
 28	    return .{ .graph = graph, .value = value };
 29	}
