 44	const Decoder = struct {
 45	    a: std.mem.Allocator,
 46	    graph: *d.Graph,
 47	    revivers: []const d.Reviver,
 48	    tape: w.Tape,
 49	    values: std.ArrayList(usize) = .empty,
 50	    cache: std.ArrayList(?d.Value) = .empty,
 51	    pending: std.ArrayList(bool) = .empty,
 52	    fn edge(self: *Decoder, token: usize, depth: usize) d.Error!d.Value {
 53	        return self.hydrate(try self.tape.reference(token), false, depth + 1);
 54	    }
 55	    fn remember(self: *Decoder, i: usize, v: d.Value) d.Value {
 56	        self.cache.items[i] = v;
 57	        return v;
 58	    }
 59	    fn child(self: *Decoder, token: usize, n: usize) d.Error!usize {
 60	        return self.tape.child(token, n);
 61	    }
 62	    fn hydrate(self: *Decoder, index: i64, standalone: bool, depth: usize) d.Error!d.Value {
 63	        switch (index) {
 64	            -1 => return .undefined,
