fn build(a: std.mem.Allocator, kind: u8, n: usize) ![]u8 {
    var w: std.ArrayList(u8) = .empty;
    switch (kind) {
        's' => { // Set of n distinct numbers
            try w.appendSlice(a, "[[\"Set\"");
            for (0..n) |i| try w.print(a, ",{d}", .{i + 1});
            try w.appendSlice(a, "]");
            for (0..n) |i| try w.print(a, ",{d}", .{i});
            try w.appendSlice(a, "]");
        },
        'o' => { // object with n distinct string keys, all -> slot 1
            try w.appendSlice(a, "[{");
            for (0..n) |i| try w.print(a, "{s}\"k{d}\":1", .{ if (i == 0) "" else ",", i });
            try w.appendSlice(a, "},0]");
        },
        'i' => { // object with n integer keys in descending JSON order
            try w.appendSlice(a, "[{");
            for (0..n) |i| try w.print(a, "{s}\"{d}\":1", .{ if (i == 0) "" else ",", n - i });
            try w.appendSlice(a, "},0]");
        },
        'p' => { // sparse array with descending indices
            try w.print(a, "[[-7,{d}", .{n * 10});
            for (0..n) |i| try w.print(a, ",{d},1", .{(n - i) * 10 - 1});
            try w.appendSlice(a, "],0]");
        },
        else => unreachable,
    }
    return w.toOwnedSlice(a);
}
